     1	// The MHPCO price list: which items the office insures at all, and what each
     2	// one is worth to it. This is catalogue knowledge, not pricing policy -- it
     3	// changes when the office revises its tariffs or takes on a new kind of item,
     4	// independently of how premiums or payouts are assessed from it.
     5	
     6	export interface Item {
     7	  type: string;
     8	  material?: string;
     9	  enchantment?: number;
    10	  cursed?: boolean;
    11	}
    12	
    13	const MAIN_ITEM_INSURANCE_VALUES: Record<string, number> = {
    14	  sword: 1000,
    15	  amulet: 600,
    16	  staff: 800,
    17	  potion: 400,
    18	};
    19	
    20	const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
    21	  sword: 100,
    22	  amulet: 60,
    23	  staff: 80,
    24	  potion: 40,
    25	};
    26	
    27	// Components -- for example runes and moonstones -- share a single list price.
    28	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
    29	export const COMPONENT_BASE_PREMIUM = 25;
    30	const COMPONENT_INSURANCE_VALUE = 250;
    31	
    32	// The office insures only the items in its catalogue; anything else is
    33	// refused rather than priced.
    34	export function isInsurable(item: Item): boolean {
    35	  return isComponent(item) || item.type in MAIN_ITEM_BASE_PREMIUMS;
    36	}
    37	
    38	export function isComponent(item: Item): boolean {
    39	  return COMPONENT_TYPES.has(item.type);
    40	}
    41	
    42	export function mainItemBasePremium(item: Item): number {
    43	  return MAIN_ITEM_BASE_PREMIUMS[item.type];
    44	}
    45	
    46	// An item's own list price, whatever kind of item it is.
    47	export function listedBasePremium(item: Item): number {
    48	  return isComponent(item) ? COMPONENT_BASE_PREMIUM : mainItemBasePremium(item);
    49	}
    50	
    51	// What the office insures an item for, independently of what it charges.
    52	export function insuranceValue(item: Item): number {
    53	  return isComponent(item)
    54	    ? COMPONENT_INSURANCE_VALUE
    55	    : MAIN_ITEM_INSURANCE_VALUES[item.type];
    56	}
===== src/scenario.ts =====
     1	// Running a scenario: the MHPCO processes a customer's steps in order, so a
     2	// quote creates a policy that a later claim can be made against.
     3	
     4	import { type Customer, quote } from "./claim-office.js";
     5	import { type Damage } from "./claim-settlement.js";
     6	import { type Item, isInsurable } from "./item-catalogue.js";
     7	import { PolicyRegister } from "./policy-register.js";
     8	
     9	export interface QuoteStep {
    10	  op: "quote";
    11	  items: Item[];
    12	}
    13	
    14	export interface ClaimStep {
    15	  op: "claim";
    16	  policy: number;
    17	  incident: { cause: string; damages: Damage[] };
    18	}
    19	
    20	export type Step = QuoteStep | ClaimStep;
    21	
    22	export interface Scenario {
    23	  customer: Customer;
    24	  steps: Step[];
    25	}
    26	
    27	export interface QuoteResult {
    28	  premium: number;
    29	}
    30	
    31	export interface ClaimResult {
    32	  payout: number;
    33	  remainingCap: number;
    34	}
    35	
    36	export type StepResult = QuoteResult | ClaimResult;
    37	
    38	// The office refuses a scenario it cannot honour rather than quoting or
    39	// settling it.
    40	export class ClaimOfficeRefusal extends Error {}
    41	
    42	function refuseUninsurableItems(items: Item[]): void {
    43	  const uninsurable = items.filter((item) => !isInsurable(item));
    44	  if (uninsurable.length > 0) {
    45	    throw new ClaimOfficeRefusal(
    46	      `the MHPCO does not insure items of type: ${uninsurable
    47	        .map((item) => item.type)
    48	        .join(", ")}`,
    49	    );
    50	  }
    51	}
    52	
    53	export function runScenario(scenario: Scenario): StepResult[] {
    54	  const policies = new PolicyRegister();
    55	  // Every quote in the scenario closes a contract, so each later quote is a
    56	  // follow-up contract for this customer.
    57	  let previousContracts = 0;
    58	
    59	  function runQuote(step: QuoteStep, reference: number): QuoteResult {
    60	    refuseUninsurableItems(step.items);
    61	    const premium = quote(scenario.customer, step.items, previousContracts);
    62	    previousContracts += 1;
    63	    policies.open(reference, step.items);
    64	    return { premium };
    65	  }
    66	
    67	  function runClaim(step: ClaimStep): ClaimResult {
    68	    return policies.settleAgainst(step.policy, step.incident.damages);
    69	  }
    70	
    71	  return scenario.steps.map((step, index) =>
    72	    step.op === "quote" ? runQuote(step, index) : runClaim(step),
    73	  );
    74	}
