     1	#!/usr/bin/env node
     2	// The claim-office command: reads a scenario as JSON on stdin and writes the
     3	// corresponding results as JSON on stdout. Transport only -- every decision
     4	// belongs to the domain modules it calls.
     5	
     6	import { ClaimOfficeRefusal, type Scenario, runScenario } from "./scenario.js";
     7	
     8	async function readStdin(): Promise<string> {
     9	  const chunks: Buffer[] = [];
    10	  for await (const chunk of process.stdin) {
    11	    chunks.push(Buffer.from(chunk));
    12	  }
    13	  return Buffer.concat(chunks).toString("utf8");
    14	}
    15	
    16	const REFUSAL_EXIT_CODE = 1;
    17	
    18	// A refused scenario produces no results: the office reports why on stderr
    19	// and exits non-zero.
    20	async function main(): Promise<void> {
    21	  const scenario = JSON.parse(await readStdin()) as Scenario;
    22	  try {
    23	    const results = runScenario(scenario);
    24	    process.stdout.write(`${JSON.stringify({ results })}\n`);
    25	  } catch (error) {
    26	    if (!(error instanceof ClaimOfficeRefusal)) {
    27	      throw error;
    28	    }
    29	    process.stderr.write(`${error.message}\n`);
    30	    process.exitCode = REFUSAL_EXIT_CODE;
    31	  }
    32	}
    33	
    34	await main();
===== src/claim-settlement.ts =====
     1	// How the MHPCO settles a claim against a policy: what the policy covers in
     2	// total, and what it will pay out. This is settlement policy, separate from
     3	// the premium policy that decides what the office charges.
     4	
     5	import { type Item, insuranceValue } from "./item-catalogue.js";
     6	
     7	const CAP_MULTIPLE = 2;
     8	const DEDUCTIBLE = 100;
     9	const REDUCED_REIMBURSEMENT_ENCHANTMENT = 8;
    10	const REDUCED_REIMBURSEMENT_RATE = 0.5;
    11	
    12	// The insurance sum is the sum of the insured items' insurance values; the
    13	// block discount affects the premium only, never the insurance sum.
    14	export function insuranceSum(items: Item[]): number {
    15	  return items.reduce((total, item) => total + insuranceValue(item), 0);
    16	}
    17	
    18	// The total payout per policy is capped at twice the insurance sum.
    19	export function policyCap(items: Item[]): number {
    20	  return insuranceSum(items) * CAP_MULTIPLE;
    21	}
    22	
    23	export interface Damage {
    24	  itemType: string;
    25	  amount: number;
    26	}
    27	
    28	export interface Settlement {
    29	  payout: number;
    30	  remainingCap: number;
    31	}
    32	
    33	// Damage to an item enchanted at this level or above is reimbursed at half.
    34	function isReducedReimbursement(item: Item): boolean {
    35	  return (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_ENCHANTMENT;
    36	}
    37	
    38	// The reimbursement clauses decide what a damage is worth before the
    39	// deductible is withheld. Dragon material is fully reimbursed, which is also
    40	// the default for an item no clause reduces, so it needs no separate branch:
    41	// where dragon material meets high enchantment the spec's examples give the
    42	// 50 % rule precedence (dragon sword, enchantment 8 or 9, damage 1000 G ->
    43	// payout 400 G).
    44	function reimbursableAmount(item: Item, damage: Damage): number {
    45	  return isReducedReimbursement(item)
    46	    ? damage.amount * REDUCED_REIMBURSEMENT_RATE
    47	    : damage.amount;
    48	}
    49	
    50	// A deductible is withheld per damage event, after the reimbursement clauses
    51	// have decided what the damage is worth.
    52	function damagePayout(item: Item, damage: Damage): number {
    53	  return reimbursableAmount(item, damage) - DEDUCTIBLE;
    54	}
    55	
    56	// Which covered item a reported damage refers to. A damage report names only
    57	// an item type, so the office has to match it against what the policy actually
    58	// covers. A damage naming a type the policy does not cover is a rejected claim,
    59	// not a settled one; until that rejection rule exists, this assumes the caller
    60	// has only passed damages the policy covers.
    61	function coveredItemFor(items: Item[], damage: Damage): Item {
    62	  return items.find((item) => item.type === damage.itemType) as Item;
    63	}
    64	
    65	// Every damage in an incident is settled on its own -- two damaged swords are
    66	// two damage events, each bearing its own deductible -- and the claim pays out
    67	// the sum of them.
    68	function claimPayout(items: Item[], damages: Damage[]): number {
    69	  return damages.reduce(
    70	    (total, damage) =>
    71	      total + damagePayout(coveredItemFor(items, damage), damage),
    72	    0,
    73	  );
    74	}
    75	
    76	// The total payout per policy is capped, so the office never pays more than
    77	// the cap the policy has left: a claim that wants more is reduced to it.
    78	function payoutWithinRemainingCap(
    79	  desiredPayout: number,
    80	  remainingCap: number,
    81	): number {
    82	  return Math.min(desiredPayout, remainingCap);
    83	}
    84	
    85	// Amounts are rounded to whole G in the MHPCO's favour: a payout is rounded
    86	// down. Intermediate amounts are kept as fractions.
    87	function roundPayoutInMhpcoFavor(payout: number): number {
    88	  return Math.floor(payout);
    89	}
    90	
    91	// Settling a claim: what the incident is worth, reduced to what the policy's
    92	// cap still permits, and what that leaves of the cap for later claims.
    93	export function settleClaim(
    94	  items: Item[],
    95	  damages: Damage[],
    96	  remainingCap: number,
    97	): Settlement {
    98	  const desiredPayout = claimPayout(items, damages);
    99	  const permittedPayout = payoutWithinRemainingCap(desiredPayout, remainingCap);
   100	  const payout = roundPayoutInMhpcoFavor(permittedPayout);
   101	  return { payout, remainingCap: remainingCap - payout };
   102	}
===== src/policy-register.ts =====
     1	// The register of policies a scenario has opened. It knows two things the
     2	// office would otherwise have to remember by hand: how a later claim addresses
     3	// an earlier policy -- by the zero-based index of the quote step that opened
     4	// it -- and how much of each policy's cap is left once claims have been settled
     5	// against it, since the cap is a per-policy total carried across claims.
     6	
     7	import { type Damage, type Settlement, policyCap, settleClaim } from "./claim-settlement.js";
     8	import { type Item } from "./item-catalogue.js";
     9	
    10	// A policy, once quoted, carries its items and whatever cap it has left.
    11	interface Policy {
    12	  items: Item[];
    13	  remainingCap: number;
    14	}
    15	
    16	export class PolicyRegister {
    17	  private readonly policies = new Map<number, Policy>();
    18	
    19	  // A quote opens a policy over its items, with the full cap still available.
    20	  open(reference: number, items: Item[]): void {
    21	    this.policies.set(reference, { items, remainingCap: policyCap(items) });
    22	  }
    23	
    24	  // Settling against a registered policy draws on the cap it has left, so what
    25	  // this claim does not exhaust remains available to the next one.
    26	  settleAgainst(reference: number, damages: Damage[]): Settlement {
    27	    const policy = this.policies.get(reference) as Policy;
    28	    const settlement = settleClaim(policy.items, damages, policy.remainingCap);
    29	    policy.remainingCap = settlement.remainingCap;
    30	    return settlement;
    31	  }
    32	}
===== src/claim-office.ts =====
     1	import {
     2	  COMPONENT_BASE_PREMIUM,
     3	  isComponent,
     4	  listedBasePremium,
     5	  mainItemBasePremium,
     6	  type Item,
     7	} from "./item-catalogue.js";
     8	
     9	export type { Item };
    10	
    11	export interface Customer {
    12	  yearsWithMHPCO: number;
    13	}
    14	
    15	const PROCESSING_FEE = 5;
    16	
    17	const BLOCK_SIZE = 3;
    18	const BLOCK_BASE_PREMIUM = 60;
    19	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
    20	const LOYALTY_YEARS = 2;
    21	const LOYALTY_DISCOUNT_RATE = 0.2;
    22	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
    23	const CURSE_SURCHARGE_RATE = 0.5;
    24	const HIGH_ENCHANTMENT_LEVEL = 5;
    25	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
    26	
    27	function sum(amounts: number[]): number {
    28	  return amounts.reduce((total, amount) => total + amount, 0);
    29	}
    30	
    31	function alikeComponentsBasePremium(alikeComponents: Item[]): number {
    32	  return alikeComponents.length === BLOCK_SIZE
    33	    ? BLOCK_BASE_PREMIUM
    34	    : alikeComponents.length * COMPONENT_BASE_PREMIUM;
    35	}
    36	
    37	// "Alike" components are components of exactly the same type, not merely of
    38	// the same family; only alike components can form a building block.
    39	function alikeKey(component: Item): string {
    40	  return component.type;
    41	}
    42	
    43	function groupAlikeComponents(components: Item[]): Item[][] {
    44	  const groups = new Map<string, Item[]>();
    45	  for (const component of components) {
    46	    const key = alikeKey(component);
    47	    const group = groups.get(key) ?? [];
    48	    group.push(component);
    49	    groups.set(key, group);
    50	  }
    51	  return [...groups.values()];
    52	}
    53	
    54	function componentsBasePremium(components: Item[]): number {
    55	  return sum(groupAlikeComponents(components).map(alikeComponentsBasePremium));
    56	}
    57	
    58	export function policyBasePremium(items: Item[]): number {
    59	  const components = items.filter(isComponent);
    60	  const mainItems = items.filter((item) => !isComponent(item));
    61	  return (
    62	    sum(mainItems.map(mainItemBasePremium)) + componentsBasePremium(components)
    63	  );
    64	}
    65	
    66	function isCursed(item: Item): boolean {
    67	  return item.cursed === true;
    68	}
    69	
    70	function isHighlyEnchanted(item: Item): boolean {
    71	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
    72	}
    73	
    74	// An item bears every risk factor it qualifies for; a cursed, highly enchanted
    75	// item therefore carries both surcharges.
    76	function itemRiskSurchargeRate(item: Item): number {
    77	  const curse = isCursed(item) ? CURSE_SURCHARGE_RATE : 0;
    78	  const highEnchantment = isHighlyEnchanted(item)
    79	    ? HIGH_ENCHANTMENT_SURCHARGE_RATE
    80	    : 0;
    81	  return curse + highEnchantment;
    82	}
    83	
    84	// A surcharge is assessed on the item's own list price, deliberately not on
    85	// its share of the policy base premium: the block discount is a policy pricing
    86	// rule, so a rune in a block is still assessed on the full 25 G.
    87	function itemRiskSurcharge(item: Item): number {
    88	  return listedBasePremium(item) * itemRiskSurchargeRate(item);
    89	}
    90	
    91	// Item-specific modifiers apply to the base premium of the affected item.
    92	function itemRiskSurcharges(items: Item[]): number {
    93	  return sum(items.map(itemRiskSurcharge));
    94	}
    95	
    96	// The customer's standing with MHPCO, as far as the premium is concerned.
    97	interface CustomerStanding {
    98	  customer: Customer;
    99	  previousContracts: number;
   100	}
   101	
   102	// Every item in a quote is treated as a first insurance, regardless of the
   103	// customer's history, so this surcharge does not depend on the customer.
   104	function firstInsuranceSurcharge(basePremium: number): number {
   105	  return basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
   106	}
   107	
   108	function isLongStanding({ customer }: CustomerStanding): boolean {
   109	  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
   110	}
   111	
   112	function loyaltyDiscount(
   113	  standing: CustomerStanding,
   114	  basePremium: number,
   115	): number {
   116	  return isLongStanding(standing) ? basePremium * LOYALTY_DISCOUNT_RATE : 0;
   117	}
   118	
   119	// Every contract after the customer's first is a follow-up contract.
   120	function isFollowUpContract({ previousContracts }: CustomerStanding): boolean {
   121	  return previousContracts > 0;
   122	}
   123	
   124	function followUpContractDiscount(
   125	  standing: CustomerStanding,
   126	  basePremium: number,
   127	): number {
   128	  return isFollowUpContract(standing)
   129	    ? basePremium * FOLLOW_UP_CONTRACT_DISCOUNT_RATE
   130	    : 0;
   131	}
   132	
   133	// Policy-wide modifiers (first insurance, loyalty, follow-up contract) all
   134	// apply to the policy base premium. Returns the net adjustment: surcharges
   135	// positive, discounts negative. Each modifier is applied to the base premium
   136	// separately rather than as a summed rate, so that intermediate amounts match
   137	// the per-modifier figures in the MHPCO's own worked examples.
   138	function policyWideModifiers(
   139	  standing: CustomerStanding,
   140	  basePremium: number,
   141	): number {
   142	  return (
   143	    firstInsuranceSurcharge(basePremium) -
   144	    loyaltyDiscount(standing, basePremium) -
   145	    followUpContractDiscount(standing, basePremium)
   146	  );
   147	}
   148	
   149	// All amounts are rounded to whole G in the MHPCO's favour. For a premium --
   150	// money flowing to MHPCO -- its favour is upwards. A payout rounds the other
   151	// way, and settlement policy owns that direction itself: the shared principle
   152	// is "never to MHPCO's disadvantage", but the direction is a fact about this
   153	// kind of amount, so each side keeps its own. Intermediate amounts are kept as
   154	// fractions; only the final premium is rounded.
   155	function roundPremiumInMhpcoFavor(premium: number): number {
   156	  return Math.ceil(premium);
   157	}
   158	
   159	// The premium the MHPCO assesses for the policy itself: the policy base
   160	// premium adjusted by the item-specific and policy-wide modifiers. The
   161	// processing fee is not part of the assessment; it is added at the very end.
   162	function assessedPremium(standing: CustomerStanding, items: Item[]): number {
   163	  const basePremium = policyBasePremium(items);
   164	  return (
   165	    basePremium +
   166	    itemRiskSurcharges(items) +
   167	    policyWideModifiers(standing, basePremium)
   168	  );
   169	}
   170	
   171	export function quote(
   172	  customer: Customer,
   173	  items: Item[],
   174	  previousContracts = 0,
   175	): number {
   176	  const standing = { customer, previousContracts };
   177	  return roundPremiumInMhpcoFavor(
   178	    assessedPremium(standing, items) + PROCESSING_FEE,
   179	  );
   180	}

